-- Jóváhagyott ERP-szakaszolás. Kizárólag saját ERP-objektumok.
begin;
alter table erp.workplans add column if not exists execution_mode text not null default 'legacy' check(execution_mode in('legacy','parts'));
alter table erp.workplans add column if not exists execution_revision bigint not null default 0;
create table erp.execution_catalog_versions(
 organization_id uuid not null references erp.organizations(id),revision bigint not null,document jsonb not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),
 primary key(organization_id,revision),foreign key(organization_id,actor_id) references erp.persons(organization_id,id),check(jsonb_typeof(document)='object'));
create index execution_catalog_actor on erp.execution_catalog_versions(organization_id,actor_id);
create table erp.execution_stages(
 organization_id uuid not null,plan_id uuid not null,id uuid not null,source_key uuid,name text not null check(length(btrim(name)) between 1 and 200),number int not null check(number>0),sort int not null check(sort>=0),opening boolean not null default false,closing boolean not null default false,unassigned boolean not null default false,active boolean not null default true,
 primary key(plan_id,id),unique(organization_id,plan_id,id),foreign key(organization_id,plan_id) references erp.workplans(organization_id,id),check(not(opening and closing)));
create unique index execution_stages_number on erp.execution_stages(plan_id,number) where active;
create unique index execution_stages_sort on erp.execution_stages(plan_id,sort) where active;
create index execution_stages_plan on erp.execution_stages(organization_id,plan_id,sort,id);
create table erp.execution_parts(
 id uuid primary key,organization_id uuid not null,plan_id uuid not null,parent_task_id uuid,template_key uuid,stage_id uuid not null,title text not null check(length(btrim(title)) between 1 and 500),description text not null default '' check(length(description)<=12000),sort int not null check(sort>=0),quantity numeric(22,6) not null check(quantity>=0),unit text not null check(length(unit) between 1 and 30),labor_bps int not null check(labor_bps between 0 and 10000),time_bps int not null check(time_bps between 0 and 10000),labor numeric(22,2) not null check(labor>=0),original_minutes numeric(22,6),planned_minutes numeric(22,6),start_date date,end_date date,
 active boolean not null default true,revision bigint not null default 1,state jsonb not null default '{"round":0,"approvals":[],"shares":[],"share_lock":0}',baseline jsonb,baseline_active boolean not null default false,
 unique(organization_id,plan_id,id),foreign key(organization_id,plan_id) references erp.workplans(organization_id,id),foreign key(organization_id,plan_id,parent_task_id) references erp.project_tasks(organization_id,plan_id,id),foreign key(organization_id,plan_id,stage_id) references erp.execution_stages(organization_id,plan_id,id),check(original_minutes is null or original_minutes>=0),check(planned_minutes is null or planned_minutes>=0),check(end_date is null or start_date is null or end_date>=start_date),check(jsonb_typeof(state->'approvals')='array' and jsonb_typeof(state->'shares')='array'),check(parent_task_id is not null or(labor=0 and labor_bps=0 and time_bps=0)));
create index execution_parts_parent on erp.execution_parts(organization_id,plan_id,parent_task_id);
create index execution_parts_stage on erp.execution_parts(organization_id,plan_id,stage_id,sort,id);
create index execution_parts_active on erp.execution_parts(plan_id,sort,id) where active;
create table erp.execution_dependencies(
 organization_id uuid not null,plan_id uuid not null,part_id uuid not null,requires_part uuid not null,
 primary key(plan_id,part_id,requires_part),foreign key(organization_id,plan_id,part_id) references erp.execution_parts(organization_id,plan_id,id),foreign key(organization_id,plan_id,requires_part) references erp.execution_parts(organization_id,plan_id,id),check(part_id<>requires_part));
create index execution_dependencies_reverse on erp.execution_dependencies(organization_id,plan_id,requires_part);
create index execution_dependencies_part on erp.execution_dependencies(organization_id,plan_id,part_id);
create table erp.execution_events(
 id uuid primary key,organization_id uuid not null,plan_id uuid,part_id uuid,actor_id uuid not null,actor_auth_id uuid not null,active_role text not null,kind text not null,request_hash text not null,request_payload jsonb not null,data jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),
 unique(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id),foreign key(organization_id,plan_id) references erp.workplans(organization_id,id),foreign key(organization_id,plan_id,part_id) references erp.execution_parts(organization_id,plan_id,id));
create index execution_events_actor on erp.execution_events(organization_id,actor_id);
create index execution_events_plan on erp.execution_events(organization_id,plan_id,created_at desc,id);
create index execution_events_part on erp.execution_events(organization_id,plan_id,part_id,created_at desc,id);
create table erp.execution_layout_versions(
 organization_id uuid not null,plan_id uuid not null,revision bigint not null,quote_version bigint not null,catalog_revision bigint not null,request_id uuid not null,document jsonb not null,checks jsonb not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),
 primary key(plan_id,revision),unique(organization_id,plan_id,revision),foreign key(organization_id,plan_id) references erp.workplans(organization_id,id),foreign key(organization_id,request_id) references erp.execution_events(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id));
create index execution_layout_org_plan on erp.execution_layout_versions(organization_id,plan_id,revision desc);
create index execution_layout_request on erp.execution_layout_versions(organization_id,request_id);
create index execution_layout_actor on erp.execution_layout_versions(organization_id,actor_id);
create table erp.construction_worksheet_part_links(
 organization_id uuid not null,worksheet_id uuid not null,person_id uuid not null,plan_id uuid not null,part_id uuid not null,
 primary key(organization_id,worksheet_id,person_id,part_id),foreign key(organization_id,worksheet_id,person_id) references erp.construction_worksheet_people(organization_id,worksheet_id,person_id) on delete cascade,foreign key(organization_id,plan_id,part_id) references erp.execution_parts(organization_id,plan_id,id));
create index execution_sheet_parts on erp.construction_worksheet_part_links(organization_id,plan_id,part_id);
do $$declare name text;begin foreach name in array array['execution_catalog_versions','execution_stages','execution_parts','execution_dependencies','execution_events','execution_layout_versions','construction_worksheet_part_links']loop execute format('alter table erp.%I enable row level security',name);execute format('alter table erp.%I force row level security',name);execute format('revoke all on erp.%I from public,anon,authenticated,service_role',name);end loop;end$$;

create function erp_private.execution_alloc(p_total numeric,p_parts jsonb,p_key text,p_digits int,p_basis int default 10000) returns jsonb language plpgsql immutable security invoker set search_path='' as $$declare result jsonb;total_units numeric;begin
 if p_basis=0 and coalesce(p_total,0)=0 then return(select jsonb_object_agg(x->>'id',case when p_total is null then 'null'::jsonb else to_jsonb('0'::text)end)from jsonb_array_elements(p_parts)x);end if;
 if p_basis<1 or p_basis>10000 or p_key not in('labor_bps','time_bps') or p_digits not in(2,6) or jsonb_typeof(p_parts) is distinct from 'array' or jsonb_array_length(p_parts)=0 or (select sum((x->>p_key)::int) from jsonb_array_elements(p_parts)x)<>p_basis or exists(select 1 from jsonb_array_elements(p_parts)x where (x->>p_key)::int not between 0 and p_basis) then raise exception 'A részfeladatok aránya összesen pontosan 100%% legyen.' using errcode='22023';end if;
 if p_total is null then select jsonb_object_agg(x->>'id','null'::jsonb) into result from jsonb_array_elements(p_parts)x;return result;end if;
 total_units:=p_total*power(10::numeric,p_digits);if p_total<0 or total_units<>trunc(total_units) then raise exception 'Hibás felosztási alap.' using errcode='22023';end if;
 with bases as(select x->>'id' id,floor(total_units*(x->>p_key)::int/p_basis) value,mod(total_units*(x->>p_key)::int,p_basis) remainder from jsonb_array_elements(p_parts)x),ranked as(select *,row_number()over(order by remainder desc,id) place,sum(value)over() all_value from bases)
 select jsonb_object_agg(id,to_jsonb(((value+case when place<=total_units-all_value then 1 else 0 end)/power(10::numeric,p_digits))::text)) into result from ranked;return result;
end$$;
create function erp_private.execution_source(p_plan uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 select coalesce(jsonb_agg(erp_private.plan_task_json(t)||jsonb_build_object('category',l.value->'pricing'->>'category','work_process',coalesce(l.value->'pricing'->'work_process',l.value->'work_process'),'metrics',jsonb_build_object('quantity',erp_private.plan_task_json(t)->>'quantity','area',calc.value->'trace'->'area','volume',calc.value->'trace'->'volume','length',calc.value->'trace'->'length','count',calc.value->'trace'->'count')) order by t.sort,t.id),'[]') into result from erp.project_tasks t join erp.workplans w on w.id=t.plan_id join erp.garden_projects g on g.id=w.project_id join erp.quote_versions v on v.organization_id=w.organization_id and v.quote_id=w.quote_id and v.version=g.accepted_quote_version left join lateral(select line.value from jsonb_array_elements(v.input->'sections')s cross join lateral jsonb_array_elements(s.value->'lines')line where line.value->>'id'=t.source_line_id)l on true left join lateral(select line.value from jsonb_array_elements(v.calculation->'sections')sec cross join lateral jsonb_array_elements(sec.value->'lines')line where line.value->>'id'=t.source_line_id)calc on true where t.plan_id=p_plan and erp_private.entry_task_active(t.id);return result;
end$$;
create function public.erp_execution_catalog_read(p_org uuid,p_actor uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v erp.execution_catalog_versions;begin
 perform erp_private.require_customer_office(p_org,p_actor);select * into v from erp.execution_catalog_versions where organization_id=p_org order by revision desc limit 1;return jsonb_build_object('revision',coalesce(v.revision,0),'document',coalesce(v.document,'{"version":1,"stages":[],"categories":[]}'));
end$$;
create function public.erp_execution_catalog_write(p_org uuid,p_actor uuid,p_request uuid,p_revision bigint,p_document jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare person uuid;current_revision bigint;prior erp.execution_events;r jsonb;stage_doc jsonb;c jsonb;step jsonb;begin
 perform erp_private.require_customer_office(p_org,p_actor);select person_id into person from erp.user_accounts where organization_id=p_org and auth_user_id=p_actor and active;perform pg_advisory_xact_lock(hashtextextended('erp-execution-catalog:'||p_org::text,0));
 select * into prior from erp.execution_events where id=p_request;if found then if prior.organization_id<>p_org or prior.actor_auth_id<>p_actor or prior.kind<>'catalog' or prior.request_payload<>p_document then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return prior.result||'{"replayed":true}';end if;
 select coalesce(max(revision),0) into current_revision from erp.execution_catalog_versions where organization_id=p_org;if p_revision is distinct from current_revision then raise exception 'A szakaszbeállítás megváltozott.' using errcode='40001';end if;
 if p_request is null or jsonb_typeof(p_document->'stages') is distinct from 'array' or jsonb_typeof(p_document->'categories') is distinct from 'array' then raise exception 'Hiányos szakaszbeállítás.' using errcode='22023';end if;
 if (select count(*) from jsonb_array_elements(p_document->'stages'))<>(select count(distinct x->>'id') from jsonb_array_elements(p_document->'stages')x) or (select count(*) from jsonb_array_elements(p_document->'stages'))<>(select count(distinct (x->>'number')::int) from jsonb_array_elements(p_document->'stages')x) then raise exception 'Ismétlődő szakasz vagy sorszám.' using errcode='22023';end if;
 for stage_doc in select value from jsonb_array_elements(p_document->'stages')loop if (stage_doc->>'id')::uuid is null or (stage_doc->>'number')::int<1 or length(btrim(coalesce(stage_doc->>'name',''))) not between 1 and 200 then raise exception 'Hibás szakasz.' using errcode='22023';end if;end loop;
 for c in select value from jsonb_array_elements(p_document->'categories')loop if (c->>'id')::uuid is null or length(btrim(coalesce(c->>'name',''))) not between 1 and 150 then raise exception 'Hibás kategóriaalap.' using errcode='22023';end if;if not coalesce((c->'process'->>'inherit')::boolean,false) then perform erp_private.execution_alloc(0,c->'process'->'steps','labor_bps',2);perform erp_private.execution_alloc(0,c->'process'->'steps','time_bps',6);for step in select value from jsonb_array_elements(c->'process'->'steps')loop if (step->>'id')::uuid is null or length(btrim(coalesce(step->>'title',''))) not between 1 and 500 or step->>'stage_id' is not null and not exists(select 1 from jsonb_array_elements(p_document->'stages')s where s->>'id'=step->>'stage_id') then raise exception 'Hibás részfolyamat vagy szakaszkapcsolat.' using errcode='22023';end if;end loop;end if;end loop;
 insert into erp.execution_catalog_versions values(p_org,current_revision+1,p_document,person,clock_timestamp());r:=jsonb_build_object('revision',current_revision+1);insert into erp.execution_events(id,organization_id,actor_id,actor_auth_id,active_role,kind,request_hash,request_payload,data,result)values(p_request,p_org,person,p_actor,'office','catalog',md5(p_document::text),p_document,'{}',r);return r;
end$$;

create function erp_private.execution_layout_validate(p_plan uuid,p_layout jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare source jsonb;parent jsonb;parts jsonb;labor jsonb;original jsonb;planned jsonb;part jsonb;stage_doc jsonb;ids uuid[];issues jsonb:='[]';result jsonb:='[]';begin
 if jsonb_typeof(p_layout->'stages') is distinct from 'array' or jsonb_typeof(p_layout->'parts') is distinct from 'array' then raise exception 'Hiányos elrendezés.' using errcode='22023';end if;
 select array_agg((x->>'id')::uuid) into ids from jsonb_array_elements(p_layout->'parts')x;
 if cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from erp.execution_parts x where x.id=any(ids) and x.plan_id<>p_plan) then raise exception 'Idegen vagy ismételt részfeladat.' using errcode='42501';end if;
 if (select count(*) from jsonb_array_elements(p_layout->'stages'))<>(select count(distinct x->>'id') from jsonb_array_elements(p_layout->'stages')x) or (select count(*) from jsonb_array_elements(p_layout->'stages'))<>(select count(distinct (x->>'number')::int) from jsonb_array_elements(p_layout->'stages')x) or (select count(*) from jsonb_array_elements(p_layout->'stages'))<>(select count(distinct (x->>'sort')::int) from jsonb_array_elements(p_layout->'stages')x) then raise exception 'Ismétlődő szakasz vagy sorszám.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_layout->'stages')x where coalesce((x->>'opening')::boolean,false) and coalesce((x->>'closing')::boolean,false)) or (select count(*) from jsonb_array_elements(p_layout->'stages')x where (x->>'opening')::boolean)>1 or (select count(*) from jsonb_array_elements(p_layout->'stages')x where (x->>'closing')::boolean)>1 then raise exception 'Egyetlen külön nyitó- és zárószakasz adható meg.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_layout->'stages')x where (x->>'opening')::boolean and (x->>'sort')::int<>(select min((a->>'sort')::int) from jsonb_array_elements(p_layout->'stages')a) or (x->>'closing')::boolean and (x->>'sort')::int<>(select max((a->>'sort')::int) from jsonb_array_elements(p_layout->'stages')a))then issues:=issues||jsonb_build_array('A nyitó- és zárószakasz helyét ellenőrizd.');end if;
 source:=erp_private.execution_source(p_plan);
 if exists(select 1 from jsonb_array_elements(p_layout->'parts')p where p->>'parent_task_id' is not null and not exists(select 1 from jsonb_array_elements(source)t where t->>'id'=p->>'parent_task_id')) then raise exception 'Idegen vagy nem aktív ajánlati sor.' using errcode='42501';end if;
 for parent in select value from jsonb_array_elements(source)loop
 select coalesce(jsonb_agg(p),'[]') into parts from jsonb_array_elements(p_layout->'parts')p where p->>'parent_task_id'=parent->>'id';
 if jsonb_array_length(parts)=0 then raise exception 'Az ajánlati sorhoz legalább egy részfeladat szükséges.' using errcode='22023';end if;
 labor:=erp_private.execution_alloc((parent->>'labor')::numeric,parts,'labor_bps',2);original:=erp_private.execution_alloc((parent->>'original_minutes')::numeric,parts,'time_bps',6);planned:=erp_private.execution_alloc((parent->>'planned_minutes')::numeric,parts,'time_bps',6);
 for part in select value from jsonb_array_elements(parts)loop result:=result||jsonb_build_array(part||jsonb_build_object('labor',labor->(part->>'id'),'original_minutes',original->(part->>'id'),'planned_minutes',planned->(part->>'id')));end loop;end loop;
 for part in select value from jsonb_array_elements(p_layout->'parts')p where p->>'parent_task_id' is null loop if coalesce((part->>'labor_bps')::int,0)<>0 or coalesce((part->>'time_bps')::int,0)<>0 then raise exception 'Belső munkalépés nem kaphat ügyfélmunkadíjat.' using errcode='22023';end if;result:=result||jsonb_build_array(part||jsonb_build_object('labor','0','original_minutes','0','planned_minutes',coalesce(part->>'planned_minutes','0')));end loop;
 for part in select value from jsonb_array_elements(result)loop if (part->>'id')::uuid is null or length(btrim(coalesce(part->>'title',''))) not between 1 and 500 or length(coalesce(part->>'description',''))>12000 or (part->>'sort')::int<0 or (part->>'quantity')::numeric<0 or length(coalesce(part->>'unit','')) not between 1 and 30 or not exists(select 1 from jsonb_array_elements(p_layout->'stages')s where s->>'id'=part->>'stage_id') or jsonb_typeof(part->'dependencies') is distinct from 'array' then raise exception 'Hiányos részfeladat.' using errcode='22023';end if;if (part->>'start_date')::date>(part->>'end_date')::date or (part->>'planned_minutes')::numeric<0 then raise exception 'Hibás időterv.' using errcode='22023';end if;if exists(select 1 from jsonb_array_elements_text(part->'dependencies')d where d::uuid=(part->>'id')::uuid or not d::uuid=any(ids)) then raise exception 'Idegen előfeltétel.' using errcode='42501';end if;end loop;
 if exists(with recursive edges as(select p->>'id' id,d.value dep from jsonb_array_elements(result)p cross join lateral jsonb_array_elements_text(p->'dependencies')d),paths(root,node)as(select id,dep from edges union select p.root,e.dep from paths p join edges e on e.id=p.node)select 1 from paths where root=node)then raise exception 'A részfeladatok előfeltételei körbe mutatnak.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(result)p cross join lateral jsonb_array_elements_text(p->'dependencies')d join jsonb_array_elements(result)b on b->>'id'=d.value join jsonb_array_elements(p_layout->'stages')bs on bs->>'id'=b->>'stage_id' join jsonb_array_elements(p_layout->'stages')ps on ps->>'id'=p->>'stage_id' where (bs->>'sort')::int>(ps->>'sort')::int)then raise exception 'Az előfeltétel nem kerülhet későbbi szakaszba.' using errcode='22023';end if;
 for stage_doc in select value from jsonb_array_elements(p_layout->'stages')loop if (stage_doc->>'id')::uuid is null or (stage_doc->>'number')::int<1 or (stage_doc->>'sort')::int<0 or length(btrim(coalesce(stage_doc->>'name',''))) not between 1 and 200 then raise exception 'Hibás szakasz.' using errcode='22023';end if;if coalesce((stage_doc->>'unassigned')::boolean,false) and exists(select 1 from jsonb_array_elements(result)p where p->>'stage_id'=stage_doc->>'id')then issues:=issues||jsonb_build_array('A besorolásra váró részfeladatokat még rendezni kell.');end if;end loop;
 return jsonb_build_object('version',1,'stages',p_layout->'stages','parts',result,'issues',issues);
end$$;

create function erp_private.execution_approvals(p_actual jsonb,p_baseline jsonb,p_enabled boolean) returns jsonb language sql immutable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(a order by (a->>'level')::int,a->>'id'),'[]') from(select value a from jsonb_array_elements(coalesce(p_actual,'[]')) union all select value||'{"reference_only":true}' from jsonb_array_elements(coalesce(p_baseline->'approvals','[]'))b where p_enabled and not exists(select 1 from jsonb_array_elements(coalesce(p_actual,'[]'))x where x->>'level'=b.value->>'level'))q
$$;
create function erp_private.execution_part_json(p erp.execution_parts) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'parent_task_id',p.parent_task_id,'template_key',p.template_key,'source_line_id',t.source_line_id,'section',coalesce(erp_private.plan_task_json(t)->>'section','Belső munkalépések'),'title',p.title,'internal_info',p.description,'quantity',p.quantity::text,'unit',p.unit,'labor',p.labor::text,'net','0.00','original_minutes',p.original_minutes::text,'planned_minutes',p.planned_minutes::text,'stage_id',p.stage_id,'needs_classification',coalesce((select unassigned from erp.execution_stages where plan_id=p.plan_id and id=p.stage_id),false),'source_title',erp_private.plan_task_json(t)->>'contract_label','sort',p.sort,'start_date',p.start_date,'end_date',p.end_date,'labor_bps',p.labor_bps,'time_bps',p.time_bps,'revision',p.revision,'round',p.state->'round','approvals',p.state->'approvals','shares',p.state->'shares','share_lock',p.state->'share_lock','baseline',p.baseline,'baseline_active',p.baseline_active,'dependencies',coalesce((select jsonb_agg(d.requires_part order by d.requires_part) from erp.execution_dependencies d where d.plan_id=p.plan_id and d.part_id=p.id),'[]')) from(select 1)x left join erp.project_tasks t on t.id=p.parent_task_id
$$;
create function erp_private.execution_balance(p_units jsonb) returns jsonb language plpgsql immutable security invoker set search_path='' as $$declare u jsonb;a jsonb;approvals jsonb;shares jsonb;item jsonb;level int;money numeric;bands jsonb:='[0,0,0,0]';people jsonb:='{}';planned numeric:=0;original numeric:=0;unknown_planned boolean:=false;unknown_original boolean:=false;begin
 for u in select value from jsonb_array_elements(p_units)loop money:=(u->>'labor')::numeric;approvals:=erp_private.execution_approvals(u->'approvals',u->'baseline',coalesce((u->>'baseline_active')::boolean,false));for level in 0..3 loop if exists(select 1 from jsonb_array_elements(approvals)x where (x->>'level')::int>=level)then bands:=jsonb_set(bands,array[level::text],to_jsonb((bands->>level)::numeric+money));end if;end loop;
 if exists(select 1 from jsonb_array_elements(approvals)x where (x->>'level')::int=0)then shares:=coalesce(u->'shares','[]');if jsonb_array_length(shares)=0 then shares:=coalesce(u->'baseline'->'shares','[]');end if;for item in select value from jsonb_array_elements(shares)loop people:=jsonb_set(people,array[item->>'person_id'],to_jsonb(coalesce((people->> (item->>'person_id'))::numeric,0)+money*(item->>'basis_points')::numeric/10000));end loop;end if;
 if u->>'planned_minutes' is null then unknown_planned:=true;else planned:=planned+(u->>'planned_minutes')::numeric;end if;if u->>'original_minutes' is null then unknown_original:=true;else original:=original+(u->>'original_minutes')::numeric;end if;end loop;
 return jsonb_build_object('accepted_parents',coalesce((select jsonb_agg(parent order by parent)from(select coalesce(x->>'parent_task_id',x->>'id')parent from jsonb_array_elements(p_units)x where not(x ? 'parent_task_id')or x->>'parent_task_id' is not null group by 1 having bool_and(exists(select 1 from jsonb_array_elements(erp_private.execution_approvals(x->'approvals',x->'baseline',coalesce((x->>'baseline_active')::boolean,false)))receipt where (receipt->>'level')::int=3)))accepted),'[]'),'levels',bands,'worker_weights',people,'planned_minutes',case when unknown_planned then null else planned end,'original_minutes',case when unknown_original then null else original end);
end$$;
create function erp_private.execution_current_units(p_plan uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 if exists(select 1 from erp.workplans where id=p_plan and execution_mode='parts')then select coalesce(jsonb_agg(erp_private.execution_part_json(p) order by p.sort,p.id),'[]') into result from erp.execution_parts p where p.plan_id=p_plan and p.active;else result:=erp_private.execution_source(p_plan);end if;return result;
end$$;
create function erp_private.execution_candidate(p_plan uuid,p_layout jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare document jsonb;part jsonb;existing erp.execution_parts;derived erp.execution_parts;parent erp.project_tasks;base jsonb;state jsonb;outparts jsonb:='[]';begin
 document:=erp_private.execution_layout_validate(p_plan,p_layout);
 for derived in select * from erp.execution_parts x where x.plan_id=p_plan and x.active and not exists(select 1 from jsonb_array_elements(document->'parts')n where n->>'id'=x.id::text)loop
 if derived.parent_task_id is not null and not exists(select 1 from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text)then raise exception 'Meglévő ajánlati részfeladat csak ellenőrzött bontással váltható ki.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text)and ((select sum((n->>'labor_bps')::int)from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text)<>derived.labor_bps or(select sum((n->>'time_bps')::int)from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text)<>derived.time_bps)then raise exception 'A bontás aránya nem egyezik a forrás részfeladattal.' using errcode='22023';end if;
 end loop;
 for part in select value from jsonb_array_elements(document->'parts')loop
 select * into existing from erp.execution_parts where id=(part->>'id')::uuid and plan_id=p_plan;
 if existing.id is not null then if existing.parent_task_id is distinct from (part->>'parent_task_id')::uuid then raise exception 'A részfeladat forrástétele nem cserélhető át.' using errcode='22023';end if;if (existing.quantity is distinct from (part->>'quantity')::numeric or existing.unit is distinct from part->>'unit') and (jsonb_array_length(existing.state->'approvals')>0 or existing.baseline_active and jsonb_array_length(coalesce(existing.baseline->'approvals','[]'))>0)then raise exception 'Átvett munkatartalom mennyisége csak jóváhagyott változáskezeléssel módosítható.' using errcode='22023';end if;if existing.labor_bps<>(part->>'labor_bps')::int or existing.time_bps<>(part->>'time_bps')::int then raise exception 'Meglévő részfeladat súlyát ellenőrzött bontással változtasd.' using errcode='22023';end if;part:=part||jsonb_build_object('state',existing.state,'baseline',existing.baseline,'baseline_active',existing.baseline_active,'original_minutes',existing.original_minutes::text,'planned_minutes',existing.planned_minutes::text);
 else
 base:=null;state:='{"round":0,"approvals":[],"shares":[],"share_lock":0}';
 if part->>'derive_from_part_id' is not null then
 select * into derived from erp.execution_parts where plan_id=p_plan and id=(part->>'derive_from_part_id')::uuid and active;
 if derived.id is null or derived.parent_task_id is distinct from (part->>'parent_task_id')::uuid then raise exception 'Idegen felosztási forrás.' using errcode='42501';end if;
 if exists(select 1 from jsonb_array_elements(document->'parts')n where n->>'id'=derived.id::text)then raise exception 'A bontás forrása nem maradhat meg párhuzamosan.' using errcode='22023';end if;
 part:=part||jsonb_build_object('labor',(erp_private.execution_alloc(derived.labor,(select jsonb_agg(n)from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text),'labor_bps',2,derived.labor_bps))->(part->>'id'),'original_minutes',(erp_private.execution_alloc(derived.original_minutes,(select jsonb_agg(n)from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text),'time_bps',6,derived.time_bps))->(part->>'id'),'planned_minutes',(erp_private.execution_alloc(derived.planned_minutes,(select jsonb_agg(n)from jsonb_array_elements(document->'parts')n where n->>'derive_from_part_id'=derived.id::text),'time_bps',6,derived.time_bps))->(part->>'id'));
 base:=jsonb_build_object('source_part_id',derived.id,'approvals',erp_private.execution_approvals(derived.state->'approvals',derived.baseline,derived.baseline_active),'shares',derived.state->'shares','share_lock',derived.state->'share_lock','round',derived.state->'round');
 else
 select * into parent from erp.project_tasks where plan_id=p_plan and id=(part->>'parent_task_id')::uuid;
 if parent.id is not null then
 if exists(select 1 from erp.workplans where id=p_plan and execution_mode='parts') and exists(select 1 from erp.execution_parts where plan_id=p_plan and parent_task_id=parent.id and active)then raise exception 'A meglévő részfeladatot jelöld ki a bontás forrásaként.' using errcode='22023';end if;
 base:=jsonb_build_object('source_task_id',parent.id,'approvals',parent.state->'approvals','shares',parent.state->'shares','share_lock',parent.state->'share_lock','round',parent.state->'round');end if;
 end if;
 if base is not null then state:=jsonb_build_object('round',coalesce((base->>'round')::int,0),'approvals','[]'::jsonb,'shares',coalesce(base->'shares','[]'),'share_lock',coalesce((base->>'share_lock')::int,0));end if;
 part:=part||jsonb_build_object('state',state,'baseline',base,'baseline_active',base is not null);
 end if;
 outparts:=outparts||jsonb_build_array(part||jsonb_build_object('approvals',part->'state'->'approvals','shares',part->'state'->'shares','share_lock',part->'state'->'share_lock'));
 end loop;return document||jsonb_build_object('parts',outparts);
end$$;
create function erp_private.execution_parent_accepted(p_task uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare t erp.project_tasks;begin
 select * into t from erp.project_tasks where id=p_task;if t.id is null or not erp_private.entry_task_active(t.id)then return false;end if;
 if exists(select 1 from erp.workplans where id=t.plan_id and execution_mode='parts')then return exists(select 1 from erp.execution_parts where parent_task_id=t.id and active)and not exists(select 1 from erp.execution_parts p where p.parent_task_id=t.id and p.active and not exists(select 1 from jsonb_array_elements(erp_private.execution_approvals(p.state->'approvals',p.baseline,p.baseline_active))a where (a->>'level')::int=3));end if;
 return exists(select 1 from jsonb_array_elements(t.state->'approvals')a where (a->>'level')::int=3);end$$;
create function erp_private.execution_project_units(p_project uuid) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(x||jsonb_build_object('approvals',erp_private.execution_approvals(x->'approvals',x->'baseline',coalesce((x->>'baseline_active')::boolean,false)))),'[]')from erp.workplans w cross join lateral jsonb_array_elements(erp_private.execution_current_units(w.id))x where w.project_id=p_project$$;

create function public.erp_execution_plan_read(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_filter jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;plan erp.workplans;parts jsonb;stages jsonb;history jsonb;events jsonb;lastpart jsonb;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);select * into plan from erp.workplans where project_id=p_project;if plan.id is null then raise exception 'Előbb hozd létre az ajánlati munkatervet.' using errcode='22023';end if;
 select coalesce(jsonb_agg(x.document order by x.sort,x.id),'[]') into parts from(select p.id,p.sort,erp_private.execution_part_json(p) document from erp.execution_parts p where p.plan_id=plan.id and p.active and (p_filter->'after_part'->>'id' is null or(p.sort,p.id)>((p_filter->'after_part'->>'sort')::int,(p_filter->'after_part'->>'id')::uuid))order by p.sort,p.id limit 100)x;
 select coalesce(jsonb_agg(to_jsonb(s) order by s.sort,s.id),'[]') into stages from erp.execution_stages s where s.plan_id=plan.id and s.active;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id desc),'[]') into events from(select e.id,e.part_id task_id,e.kind,e.active_role,e.actor_id,e.data,e.created_at from erp.execution_events e where e.plan_id=plan.id and e.part_id is not null and (p_filter->'before_event'->>'id' is null or(e.created_at,e.id)<((p_filter->'before_event'->>'time')::timestamptz,(p_filter->'before_event'->>'id')::uuid))order by e.created_at desc,e.id desc limit 100)x;
 if p_role='office' then select coalesce(jsonb_agg(to_jsonb(x) order by x.revision desc),'[]') into history from(select v.revision,v.quote_version,v.catalog_revision,v.created_at,v.actor_id,v.checks from erp.execution_layout_versions v where v.plan_id=plan.id and(p_filter->>'before_revision' is null or v.revision<(p_filter->>'before_revision')::bigint)order by v.revision desc limit 100)x;end if;
 lastpart:=parts->-1;
 return jsonb_build_object('context',ctx,'plan',to_jsonb(plan),'stages',stages,'tasks',parts,'events',events,'part_cursor',case when jsonb_array_length(parts)=100 then jsonb_build_object('sort',lastpart->'sort','id',lastpart->'id') else null end,'event_cursor',case when jsonb_array_length(events)=100 then jsonb_build_object('time',events->-1->'created_at','id',events->-1->'id') else null end,'history',case when p_role='office' then history else '[]'::jsonb end,'saved_layout',case when p_role='office' and p_filter->>'layout_revision' is not null then(select document from erp.execution_layout_versions where plan_id=plan.id and revision=(p_filter->>'layout_revision')::bigint)else null end,'catalog_snapshot',case when p_role='office' then(select v.input->'execution_catalog' from erp.quote_versions v join erp.garden_projects g on g.accepted_quote_id=v.quote_id and g.accepted_quote_version=v.version where g.id=p_project)else null end,'source_tasks',case when p_role='office' then erp_private.execution_source(plan.id) else '[]'::jsonb end);
end$$;
create function public.erp_execution_layout_preview(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_revision bigint,p_layout jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;plan erp.workplans;document jsonb;before_balance jsonb;after_balance jsonb;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if not(ctx->>'can_edit')::boolean then raise exception 'A kivitelezési szerkezetet csak az iroda szerkesztheti.' using errcode='42501';end if;select * into plan from erp.workplans where project_id=p_project;if plan.id is null or p_revision is distinct from plan.revision then raise exception 'A munkaterv megváltozott.' using errcode='40001';end if;
 document:=erp_private.execution_candidate(plan.id,p_layout);before_balance:=erp_private.execution_balance(erp_private.execution_current_units(plan.id));after_balance:=erp_private.execution_balance(document->'parts');
 return jsonb_build_object('revision',plan.revision,'layout',document,'checks',jsonb_build_object('before',before_balance,'after',after_balance,'preserved',before_balance=after_balance),'fingerprint',md5(jsonb_build_object('revision',plan.revision,'quote_version',plan.quote_version,'layout',document)::text));
end$$;
create function public.erp_execution_layout_write(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_request uuid,p_revision bigint,p_layout jsonb,p_fingerprint text,p_catalog_revision bigint default 0,p_activate boolean default true) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;plan erp.workplans;prior erp.execution_events;preview jsonb;document jsonb;part jsonb;stage_doc jsonb;before_document jsonb;result jsonb;kind text;person uuid;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if not(ctx->>'can_edit')::boolean then raise exception 'A kivitelezési szerkezetet csak az iroda szerkesztheti.' using errcode='42501';end if;person:=(ctx->>'person_id')::uuid;select * into plan from erp.workplans where project_id=p_project for update;
 select * into prior from erp.execution_events where id=p_request;if found then if prior.plan_id<>plan.id or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.kind<>'layout' or prior.request_payload<>jsonb_build_object('layout',p_layout,'activate',p_activate,'catalog_revision',p_catalog_revision)then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return prior.result||'{"replayed":true}';end if;
 if p_request is null or p_revision is distinct from plan.revision then raise exception 'A munkaterv megváltozott.' using errcode='40001';end if;
 if p_catalog_revision<>0 and not exists(select 1 from erp.execution_catalog_versions where organization_id=plan.organization_id and revision=p_catalog_revision)then raise exception 'A kivitelezési alapváltozat hiányzik.' using errcode='22023';end if;
 preview:=public.erp_execution_layout_preview(p_actor,p_session,p_project,p_role,p_revision,p_layout);if p_fingerprint is distinct from preview->>'fingerprint' then raise exception 'A mentési előnézet megváltozott.' using errcode='40001';end if;
 document:=preview->'layout';if (plan.execution_mode='parts' or p_activate)and jsonb_array_length(document->'issues')>0 then raise exception 'Előbb rendezd a szakaszbesorolást.' using errcode='22023';end if;
 if not(preview->'checks'->>'preserved')::boolean then raise exception 'A szerkezeti változás átvételt, időkeretet vagy jóváírást módosítana. Ellenőrzött felosztás szükséges.' using errcode='22023';end if;
 select jsonb_build_object('stages',coalesce((select jsonb_agg(to_jsonb(x)) from erp.execution_stages x where x.plan_id=plan.id and x.active),'[]'),'parts',erp_private.execution_current_units(plan.id)) into before_document;
 update erp.execution_stages set active=false where plan_id=plan.id;
 for stage_doc in select value from jsonb_array_elements(document->'stages')loop insert into erp.execution_stages(organization_id,plan_id,id,source_key,name,number,sort,opening,closing,unassigned)values(plan.organization_id,plan.id,(stage_doc->>'id')::uuid,(stage_doc->>'source_key')::uuid,stage_doc->>'name',(stage_doc->>'number')::int,(stage_doc->>'sort')::int,coalesce((stage_doc->>'opening')::boolean,false),coalesce((stage_doc->>'closing')::boolean,false),coalesce((stage_doc->>'unassigned')::boolean,false))on conflict(plan_id,id)do update set source_key=excluded.source_key,name=excluded.name,number=excluded.number,sort=excluded.sort,opening=excluded.opening,closing=excluded.closing,unassigned=excluded.unassigned,active=true;end loop;
 update erp.execution_parts set active=false where plan_id=plan.id;
 for part in select value from jsonb_array_elements(document->'parts')loop insert into erp.execution_parts(id,organization_id,plan_id,parent_task_id,template_key,stage_id,title,description,sort,quantity,unit,labor_bps,time_bps,labor,original_minutes,planned_minutes,start_date,end_date,state,baseline,baseline_active)values((part->>'id')::uuid,plan.organization_id,plan.id,(part->>'parent_task_id')::uuid,(part->>'template_key')::uuid,(part->>'stage_id')::uuid,part->>'title',coalesce(part->>'description',''),(part->>'sort')::int,(part->>'quantity')::numeric,part->>'unit',(part->>'labor_bps')::int,(part->>'time_bps')::int,(part->>'labor')::numeric,(part->>'original_minutes')::numeric,(part->>'planned_minutes')::numeric,(part->>'start_date')::date,(part->>'end_date')::date,part->'state',nullif(part->'baseline','null'),coalesce((part->>'baseline_active')::boolean,false))on conflict(id)do update set stage_id=excluded.stage_id,title=excluded.title,description=excluded.description,sort=excluded.sort,quantity=excluded.quantity,unit=excluded.unit,labor_bps=excluded.labor_bps,time_bps=excluded.time_bps,labor=excluded.labor,original_minutes=excluded.original_minutes,planned_minutes=excluded.planned_minutes,start_date=excluded.start_date,end_date=excluded.end_date,state=excluded.state,baseline=excluded.baseline,baseline_active=excluded.baseline_active,revision=erp.execution_parts.revision+1,active=true;end loop;
 delete from erp.execution_dependencies where plan_id=plan.id;
 for part in select value from jsonb_array_elements(document->'parts')loop insert into erp.execution_dependencies select plan.organization_id,plan.id,(part->>'id')::uuid,value::uuid from jsonb_array_elements_text(part->'dependencies');end loop;
 update erp.workplans set execution_mode=case when p_activate then 'parts' else execution_mode end,execution_revision=execution_revision+1,revision=revision+1,updated_at=clock_timestamp()where id=plan.id returning * into plan;
 result:=jsonb_build_object('revision',plan.revision,'execution_revision',plan.execution_revision,'mode',plan.execution_mode);
 insert into erp.execution_events(id,organization_id,plan_id,actor_id,actor_auth_id,active_role,kind,request_hash,request_payload,data,result)values(p_request,plan.organization_id,plan.id,person,p_actor,p_role,'layout',md5(p_layout::text),jsonb_build_object('layout',p_layout,'activate',p_activate,'catalog_revision',p_catalog_revision),jsonb_build_object('before',before_document,'after',document,'checks',preview->'checks'),result);
 insert into erp.execution_layout_versions values(plan.organization_id,plan.id,plan.execution_revision,plan.quote_version,p_catalog_revision,p_request,document,preview->'checks',person,clock_timestamp());return result;
end$$;
create function public.erp_execution_part_context(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_task uuid,p_request uuid,p_command jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;p erp.execution_parts;prior erp.execution_events;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if not(ctx->>'can_act')::boolean then raise exception 'Átvétel csak futó kertépítésen rögzíthető.' using errcode='42501';end if;
 select part.* into p from erp.execution_parts part join erp.workplans plan on plan.id=part.plan_id where plan.project_id=p_project and plan.execution_mode='parts' and part.id=p_task and part.active;if p.id is null or p.parent_task_id is not null and not erp_private.entry_task_active(p.parent_task_id)then raise exception 'A részfeladat nem elérhető.' using errcode='42501';end if;
 if exists(select 1 from erp.execution_stages where plan_id=p.plan_id and id=p.stage_id and unassigned)then raise exception 'A módosított munkatartalom részfeladatait előbb az iroda sorolja be.'using errcode='42501';end if;
 select * into prior from erp.execution_events where id=p_request;if found then if prior.part_id<>p_task or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.request_payload<>p_command then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return prior.result||'{"replayed":true}';end if;
 return jsonb_build_object('execution',true,'context',ctx,'task',erp_private.execution_part_json(p));end$$;
create function public.erp_execution_part_write(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_task uuid,p_request uuid,p_revision bigint,p_command jsonb,p_state jsonb,p_event jsonb,p_minutes text) returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb;taskrow erp.execution_parts;plan erp.workplans;prior erp.execution_events;action_kind text:=p_command->>'type';rank int;level int;subject uuid;recipient uuid;last_approval jsonb;highest int;person uuid;future_day timestamptz;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if not (ctx->>'can_act')::boolean then raise exception 'Átvétel csak futó kertépítésen rögzíthető.' using errcode='42501';end if;
 person:=(ctx->>'person_id')::uuid;rank:=case p_role when 'office' then 3 when 'construction_lead' then 2 when 'client' then 4 else 1 end;
 select * into plan from erp.workplans where project_id=p_project for update;if plan.execution_mode<>'parts' then raise exception 'A részfeladatos munkaterv nem aktív.' using errcode='40001';end if;
 select * into taskrow from erp.execution_parts where id=p_task and plan_id=plan.id and active for update;if not found then raise exception 'Idegen munkafázis.' using errcode='42501';end if;
 select * into prior from erp.execution_events where id=p_request;if found then if prior.part_id<>p_task or prior.kind<>action_kind or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.request_payload<>p_command then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return jsonb_build_object('revision',(prior.result->>'revision')::bigint,'replayed',true);end if;
 if exists(select 1 from erp.execution_stages where plan_id=taskrow.plan_id and id=taskrow.stage_id and unassigned)then raise exception 'A módosított munkatartalom részfeladatait előbb az iroda sorolja be.'using errcode='42501';end if;
 if p_request is null or p_revision is null or p_revision<>taskrow.revision then raise exception 'A fázis megváltozott. Frissítsd az adatokat.' using errcode='40001';end if;
 if p_event->>'id' is distinct from p_request::text or p_event->>'task_id' is distinct from p_task::text or p_event->>'actor_id' is distinct from person::text or p_event->>'role' is distinct from p_role or p_event->>'kind' is distinct from action_kind or p_event->'before'->'approvals' is distinct from taskrow.state->'approvals' or p_event->'before'->'shares' is distinct from taskrow.state->'shares' then raise exception 'Érvénytelen eseménykapcsolat.' using errcode='22023';end if;
 if jsonb_typeof(p_state->'approvals') is distinct from 'array' or jsonb_typeof(p_state->'shares') is distinct from 'array' or (p_state->>'share_lock')::int not between 0 and 3 or jsonb_array_length(p_state->'approvals')>400 or jsonb_array_length(p_state->'shares')>100 then raise exception 'Érvénytelen átvételi állapot.' using errcode='22023';end if;
 if plan.execution_mode<>'parts' then raise exception 'A részfeladatos munkaterv nincs élesítve.' using errcode='42501';end if;
 if action_kind='accept' and p_role='client' and not exists(select 1 from jsonb_array_elements(erp_private.execution_approvals(taskrow.state->'approvals',taskrow.baseline,taskrow.baseline_active))a where (a->>'level')::int=2)then raise exception 'Előbb az iroda vegye át ezt a részfeladatot.' using errcode='42501';end if;
 if action_kind='accept' then
  last_approval:=p_state->'approvals'->(jsonb_array_length(p_state->'approvals')-1);level:=(last_approval->>'level')::int;
  if jsonb_array_length(p_state->'approvals')<>jsonb_array_length(taskrow.state->'approvals')+1 or (p_state->'approvals')-(jsonb_array_length(p_state->'approvals')-1) is distinct from taskrow.state->'approvals' or last_approval->>'actor_id' is distinct from person::text or last_approval->>'role' is distinct from p_role or last_approval->>'id' is distinct from p_request::text or level not between 0 and 3 or (p_role='client' and level<>3) or (p_role<>'client' and (level=3 or level>=rank)) then raise exception 'Jogosulatlan átvételi szint.' using errcode='42501';end if;
  if jsonb_array_length(last_approval->'subjects')<1 then raise exception 'Hiányzó tényleges személy.' using errcode='22023';end if;
  for subject in select value::uuid from jsonb_array_elements_text(last_approval->'subjects') loop if not (ctx->'subjects'->level::text) ? subject::text or ((rank=1 or p_role='client') and subject<>person) then raise exception 'Jogosulatlan képviselt személy.' using errcode='42501';end if;end loop;
  if exists(select 1 from jsonb_array_elements(taskrow.state->'approvals')a where a->>'actor_id'=person::text and (a->>'level')::int=level and a->'subjects'=last_approval->'subjects') then raise exception 'Ezt az átvételt már rögzítettük.' using errcode='40001';end if;
 elsif action_kind='reject' then
  level:=case p_role when 'client' then 3 when 'office' then 2 when 'construction_lead' then 1 else 0 end;
  if level=0 or length(btrim(coalesce(p_event->>'reason','')))=0 or jsonb_array_length(p_state->'approvals')<>0 or (p_state->>'round')::bigint<>(taskrow.state->>'round')::bigint+1 or p_state->'shares' is distinct from taskrow.state->'shares' or p_state->'share_lock' is distinct from taskrow.state->'share_lock' then raise exception 'Érvénytelen visszaküldés.' using errcode='42501';end if;
  recipient:=(p_event->>'recipient')::uuid;if recipient is null or not (ctx->'subjects'->'0') ? recipient::text then raise exception 'Nem jogosult javítási címzett.' using errcode='42501';end if;
 elsif action_kind='shares' then
  if p_role='client' or rank<(taskrow.state->>'share_lock')::int or p_state->'approvals' is distinct from taskrow.state->'approvals' or (rank=1 and not exists(select 1 from jsonb_array_elements(taskrow.state->'approvals')a where (a->>'level')::int=0 and a->'subjects' ? person::text)) then raise exception 'A megosztás magasabb szinten zárolt vagy nem saját munkafázis.' using errcode='42501';end if;
 elsif action_kind='time' then
  if p_role<>'office' or p_minutes is null or p_state->'approvals' is distinct from taskrow.state->'approvals' or p_state->'shares' is distinct from taskrow.state->'shares' or p_state->'share_lock' is distinct from taskrow.state->'share_lock' then raise exception 'Az időtervet csak az iroda módosíthatja.' using errcode='42501';end if;
 else raise exception 'Ismeretlen átvételi művelet.' using errcode='22023';end if;
 if action_kind<>'reject' and p_state->'round' is distinct from taskrow.state->'round' then raise exception 'Az átvételi kör nem írható át.' using errcode='22023';end if;
 if action_kind='shares' or (action_kind='accept' and p_state->'shares' is distinct from taskrow.state->'shares') then
  if rank>3 or rank<(taskrow.state->>'share_lock')::int or (p_state->>'share_lock')::int<>greatest(rank,(taskrow.state->>'share_lock')::int) or jsonb_array_length(p_state->'shares')=0 or (select sum((s->>'basis_points')::int) from jsonb_array_elements(p_state->'shares')s)<>10000 or exists(select 1 from jsonb_array_elements(p_state->'shares')s where (s->>'basis_points')::int not between 1 and 10000) or (select count(distinct s->>'person_id') from jsonb_array_elements(p_state->'shares')s)<>jsonb_array_length(p_state->'shares') then raise exception 'Hibás vagy zárolt teljesítménymegosztás.' using errcode='42501';end if;
  for subject in select (s->>'person_id')::uuid from jsonb_array_elements(p_state->'shares')s loop
   if not (ctx->'subjects'->'0') ? subject::text and not exists(select 1 from jsonb_array_elements(taskrow.state->'shares')s where s->>'person_id'=subject::text) then raise exception 'Idegen teljesítményrészesedés.' using errcode='42501';end if;
   if rank=1 and not exists(select 1 from jsonb_array_elements(p_state->'approvals')a where (a->>'level')::int=0 and a->'subjects' ? subject::text) then raise exception 'Dolgozó csak a fázis tényleges résztvevőit oszthatja meg.' using errcode='42501';end if;
  end loop;
 end if;
 update erp.execution_parts set baseline_active=case when action_kind='reject' then false else baseline_active end,state=p_state,planned_minutes=case when action_kind='time' then p_minutes::numeric else planned_minutes end,revision=revision+1 where id=p_task returning * into taskrow;
 update erp.workplans set revision=revision+1,updated_at=now() where id=plan.id;
 insert into erp.task_events(id,organization_id,project_id,task_id,actor_id,actor_auth_id,active_role,kind,request_payload,data,result_revision) values(p_request,plan.organization_id,p_project,taskrow.parent_task_id,person,p_actor,p_role,action_kind,p_command,p_event||jsonb_build_object('execution_part_id',p_task),taskrow.revision);
 insert into erp.execution_events(id,organization_id,plan_id,part_id,actor_id,actor_auth_id,active_role,kind,request_hash,request_payload,data,result)values(p_request,plan.organization_id,plan.id,p_task,person,p_actor,p_role,action_kind,md5(p_command::text),p_command,p_event,jsonb_build_object('revision',taskrow.revision));
 if action_kind='reject' then
  update erp.work_notifications n set completed_at=now() where n.task_id=p_task and n.kind in ('review','repair','attribution') and n.completed_at is null;
  insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind,level) values(plan.organization_id,p_project,p_task,p_request,recipient,'repair',0);
  for subject in select distinct value::uuid from jsonb_array_elements_text(coalesce(p_event->'affected_actors','[]')||coalesce(p_event->'affected_subjects','[]')) loop
   if exists(select 1 from erp.persons where organization_id=plan.organization_id and id=subject) then insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,subject,'info') on conflict do nothing;end if;end loop;
 elsif action_kind='accept' then
  select max((a->>'level')::int) into highest from jsonb_array_elements(p_state->'approvals')a;
  update erp.work_notifications n set completed_at=now() where n.task_id=p_task and n.completed_at is null and ((n.kind='review' and n.level<=highest) or (n.kind='repair' and highest>=0));
  if level<3 and highest<level+1 then
   for recipient in select value::uuid from jsonb_array_elements_text(ctx->'subjects'->(level+1)::text) loop
    if recipient<>person then insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind,level) values(plan.organization_id,p_project,p_task,p_request,recipient,'review',level+1) on conflict do nothing;end if;end loop;
  end if;
 elsif action_kind='shares' then
  for recipient in select distinct (s->>'person_id')::uuid from jsonb_array_elements(coalesce(p_event->'before'->'shares','[]')||p_state->'shares')s loop
   insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,recipient,'info') on conflict do nothing;end loop;
 end if;
 if action_kind in ('shares','accept') and rank>=2 then
  for subject in select (s->>'person_id')::uuid from jsonb_array_elements(p_state->'shares')s loop
   if not exists(select 1 from erp.project_assignments a where a.organization_id=plan.organization_id and a.project_id=p_project and a.person_id=subject and a.revoked_at is null and a.valid_from<=now() and (a.valid_until is null or a.valid_until>now())) and not exists(select 1 from erp.person_roles r where r.organization_id=plan.organization_id and r.person_id=subject and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now())) then
    if p_role='office' then
     select min(a.valid_from) into future_day from erp.project_assignments a where a.organization_id=plan.organization_id and a.project_id=p_project and a.person_id=subject and a.revoked_at is null and a.valid_from>now();
     insert into erp.project_assignments(organization_id,project_id,person_id,role,valid_from,valid_until,created_by) values(plan.organization_id,p_project,subject,'construction_worker',now(),future_day,p_actor);
    else for recipient in select value::uuid from jsonb_array_elements_text(ctx->'subjects'->'2') loop insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,recipient,'assignment') on conflict do nothing;end loop;end if;
   end if;
  end loop;
 end if;
 return jsonb_build_object('revision',taskrow.revision);end$$;

create or replace function public.erp_plan_graph_save(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_request uuid,p_revision bigint,p_tasks jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb;plan erp.workplans;prior erp.task_events;row jsonb;before jsonb;ids uuid[];recipient uuid;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if exists(select 1 from erp.workplans where project_id=p_project and execution_mode='parts')then raise exception 'Új részfeladatos munkaterv érhető el. Frissítsd a nézetet.' using errcode='40001';end if;if not (ctx->>'can_edit')::boolean then raise exception 'A munkatervet csak irodai munkaszereppel szerkesztheted.' using errcode='42501';end if;
 select * into plan from erp.workplans where project_id=p_project for update;if not found then raise exception 'A munkaterv nincs létrehozva.' using errcode='22023';end if;
 select * into prior from erp.task_events where id=p_request;if found then if prior.project_id<>p_project or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.kind<>'graph' or prior.request_payload<>p_tasks then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return jsonb_build_object('revision',prior.result_revision,'replayed',true);end if;
 if p_revision is null or p_revision<>plan.revision then raise exception 'A munkaterv megváltozott.' using errcode='40001';end if;
 if p_request is null or jsonb_typeof(p_tasks) is distinct from 'array' or jsonb_array_length(p_tasks)<>(select count(*) from erp.project_tasks t where t.plan_id=plan.id and erp_private.entry_task_active(t.id)) then raise exception 'A munkafázisok hiányosak.' using errcode='22023';end if;
 select array_agg((x->>'id')::uuid) into ids from jsonb_array_elements(p_tasks)x;
 if cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not exists(select 1 from erp.project_tasks t where t.id=x and t.plan_id=plan.id and erp_private.entry_task_active(t.id))) then raise exception 'Idegen vagy ismételt munkafázis.' using errcode='42501';end if;
 select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'sort',t.sort,'start_date',t.start_date,'end_date',t.end_date,'internal_info',t.internal_info,'dependencies',coalesce((select jsonb_agg(d.requires_task order by d.requires_task) from erp.task_dependencies d where d.task_id=t.id),'[]')) order by t.sort,t.id) into before from erp.project_tasks t where t.plan_id=plan.id and erp_private.entry_task_active(t.id);
 delete from erp.task_dependencies where plan_id=plan.id;
 for row in select * from jsonb_array_elements(p_tasks) loop
 if jsonb_typeof(row->'dependencies') is distinct from 'array' or jsonb_array_length(row->'dependencies')>1000 or exists(select 1 from jsonb_object_keys(row)k where k not in ('id','title','sort','start_date','end_date','dependencies','internal_info')) then raise exception 'Nem szerkeszthető tervadat.' using errcode='22023';end if;
 update erp.project_tasks set title=btrim(row->>'title'),sort=(row->>'sort')::integer,start_date=(row->>'start_date')::date,end_date=(row->>'end_date')::date,internal_info=coalesce(row->>'internal_info',''),revision=revision+1 where plan_id=plan.id and id=(row->>'id')::uuid;
 insert into erp.task_dependencies(organization_id,plan_id,task_id,requires_task) select plan.organization_id,plan.id,(row->>'id')::uuid,value::uuid from jsonb_array_elements_text(row->'dependencies');
 end loop;
 if (select count(*) from erp.task_dependencies where plan_id=plan.id)>5000 then raise exception 'Túl sok előfeltétel.' using errcode='22023';end if;
 if exists(with recursive paths(root,node) as (select task_id,requires_task from erp.task_dependencies where plan_id=plan.id union select p.root,d.requires_task from paths p join erp.task_dependencies d on d.task_id=p.node and d.plan_id=plan.id) select 1 from paths where root=node) then raise exception 'Körkörös előfeltétel nem menthető.' using errcode='22023';end if;
 update erp.workplans set revision=revision+1,updated_at=now() where id=plan.id returning * into plan;
 insert into erp.task_events(id,organization_id,project_id,actor_id,actor_auth_id,active_role,kind,request_payload,data,result_revision) values(p_request,plan.organization_id,p_project,(ctx->>'person_id')::uuid,p_actor,p_role,'graph',p_tasks,jsonb_build_object('before',before,'after',p_tasks),plan.revision);
 for recipient in select distinct a.person_id from erp.project_assignments a where a.organization_id=plan.organization_id and a.project_id=p_project and a.revoked_at is null and a.valid_from<=now() and (a.valid_until is null or a.valid_until>now()) loop
 insert into erp.work_notifications(organization_id,project_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_request,recipient,'info') on conflict do nothing;end loop;
 return jsonb_build_object('revision',plan.revision);end$$;

create or replace function public.erp_plan_task_context(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_task uuid,p_request uuid,p_command jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;t erp.project_tasks;prior erp.task_events;begin
 if not erp_private.entry_task_active(p_task) then raise exception 'A munkafázis már nem az aktuális megállapodás része.' using errcode='40001';end if;
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if exists(select 1 from erp.workplans where project_id=p_project and execution_mode='parts')then raise exception 'Új részfeladatos munkaterv érhető el. Frissítsd a nézetet.' using errcode='40001';end if;if not (ctx->>'can_act')::boolean then raise exception 'Átvétel csak külön elindított kertépítésen rögzíthető.' using errcode='42501';end if;
 select * into t from erp.project_tasks where id=p_task and plan_id in(select id from erp.workplans where project_id=p_project);if not found then raise exception 'A munkafázis nem elérhető.' using errcode='42501';end if;
 select * into prior from erp.task_events where id=p_request;if found then if prior.task_id<>p_task or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.request_payload<>p_command then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return jsonb_build_object('replayed',true,'revision',prior.result_revision);end if;
 return jsonb_build_object('context',ctx,'task',erp_private.plan_task_json(t));end$$;

create or replace function public.erp_plan_task_save(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_task uuid,p_request uuid,p_revision bigint,p_command jsonb,p_state jsonb,p_event jsonb,p_minutes text) returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb;taskrow erp.project_tasks;plan erp.workplans;prior erp.task_events;action_kind text:=p_command->>'type';rank int;level int;subject uuid;recipient uuid;last_approval jsonb;highest int;person uuid;future_day timestamptz;begin
 if not erp_private.entry_task_active(p_task) then raise exception 'A munkafázis már nem az aktuális megállapodás része.' using errcode='40001';end if;
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if exists(select 1 from erp.workplans where project_id=p_project and execution_mode='parts')then raise exception 'Új részfeladatos munkaterv érhető el. Frissítsd a nézetet.' using errcode='40001';end if;if not (ctx->>'can_act')::boolean then raise exception 'Átvétel csak futó kertépítésen rögzíthető.' using errcode='42501';end if;
 person:=(ctx->>'person_id')::uuid;rank:=case p_role when 'office' then 3 when 'construction_lead' then 2 when 'client' then 4 else 1 end;
 select * into plan from erp.workplans where project_id=p_project for update;
 select * into taskrow from erp.project_tasks where id=p_task and plan_id=plan.id for update;if not found then raise exception 'Idegen munkafázis.' using errcode='42501';end if;
 select * into prior from erp.task_events where id=p_request;if found then if prior.task_id<>p_task or prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.request_payload<>p_command then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return jsonb_build_object('revision',prior.result_revision,'replayed',true);end if;
 if p_request is null or p_revision is null or p_revision<>taskrow.revision then raise exception 'A fázis megváltozott. Frissítsd az adatokat.' using errcode='40001';end if;
 if p_event->>'id' is distinct from p_request::text or p_event->>'task_id' is distinct from p_task::text or p_event->>'actor_id' is distinct from person::text or p_event->>'role' is distinct from p_role or p_event->>'kind' is distinct from action_kind or p_event->'before'->'approvals' is distinct from taskrow.state->'approvals' or p_event->'before'->'shares' is distinct from taskrow.state->'shares' then raise exception 'Érvénytelen eseménykapcsolat.' using errcode='22023';end if;
 if jsonb_typeof(p_state->'approvals') is distinct from 'array' or jsonb_typeof(p_state->'shares') is distinct from 'array' or (p_state->>'share_lock')::int not between 0 and 3 or jsonb_array_length(p_state->'approvals')>400 or jsonb_array_length(p_state->'shares')>100 then raise exception 'Érvénytelen átvételi állapot.' using errcode='22023';end if;
 if action_kind='accept' then
  last_approval:=p_state->'approvals'->(jsonb_array_length(p_state->'approvals')-1);level:=(last_approval->>'level')::int;
  if jsonb_array_length(p_state->'approvals')<>jsonb_array_length(taskrow.state->'approvals')+1 or (p_state->'approvals')-(jsonb_array_length(p_state->'approvals')-1) is distinct from taskrow.state->'approvals' or last_approval->>'actor_id' is distinct from person::text or last_approval->>'role' is distinct from p_role or last_approval->>'id' is distinct from p_request::text or level not between 0 and 3 or (p_role='client' and level<>3) or (p_role<>'client' and (level=3 or level>=rank)) then raise exception 'Jogosulatlan átvételi szint.' using errcode='42501';end if;
  if jsonb_array_length(last_approval->'subjects')<1 then raise exception 'Hiányzó tényleges személy.' using errcode='22023';end if;
  for subject in select value::uuid from jsonb_array_elements_text(last_approval->'subjects') loop if not (ctx->'subjects'->level::text) ? subject::text or ((rank=1 or p_role='client') and subject<>person) then raise exception 'Jogosulatlan képviselt személy.' using errcode='42501';end if;end loop;
  if exists(select 1 from jsonb_array_elements(taskrow.state->'approvals')a where a->>'actor_id'=person::text and (a->>'level')::int=level and a->'subjects'=last_approval->'subjects') then raise exception 'Ezt az átvételt már rögzítettük.' using errcode='40001';end if;
 elsif action_kind='reject' then
  level:=case p_role when 'client' then 3 when 'office' then 2 when 'construction_lead' then 1 else 0 end;
  if level=0 or length(btrim(coalesce(p_event->>'reason','')))=0 or jsonb_array_length(p_state->'approvals')<>0 or (p_state->>'round')::bigint<>(taskrow.state->>'round')::bigint+1 or p_state->'shares' is distinct from taskrow.state->'shares' or p_state->'share_lock' is distinct from taskrow.state->'share_lock' then raise exception 'Érvénytelen visszaküldés.' using errcode='42501';end if;
  recipient:=(p_event->>'recipient')::uuid;if recipient is null or not (ctx->'subjects'->'0') ? recipient::text then raise exception 'Nem jogosult javítási címzett.' using errcode='42501';end if;
 elsif action_kind='shares' then
  if p_role='client' or rank<(taskrow.state->>'share_lock')::int or p_state->'approvals' is distinct from taskrow.state->'approvals' or (rank=1 and not exists(select 1 from jsonb_array_elements(taskrow.state->'approvals')a where (a->>'level')::int=0 and a->'subjects' ? person::text)) then raise exception 'A megosztás magasabb szinten zárolt vagy nem saját munkafázis.' using errcode='42501';end if;
 elsif action_kind='time' then
  if p_role<>'office' or p_minutes is null or p_state->'approvals' is distinct from taskrow.state->'approvals' or p_state->'shares' is distinct from taskrow.state->'shares' or p_state->'share_lock' is distinct from taskrow.state->'share_lock' then raise exception 'Az időtervet csak az iroda módosíthatja.' using errcode='42501';end if;
 else raise exception 'Ismeretlen átvételi művelet.' using errcode='22023';end if;
 if action_kind<>'reject' and p_state->'round' is distinct from taskrow.state->'round' then raise exception 'Az átvételi kör nem írható át.' using errcode='22023';end if;
 if action_kind='shares' or (action_kind='accept' and p_state->'shares' is distinct from taskrow.state->'shares') then
  if rank>3 or rank<(taskrow.state->>'share_lock')::int or (p_state->>'share_lock')::int<>greatest(rank,(taskrow.state->>'share_lock')::int) or jsonb_array_length(p_state->'shares')=0 or (select sum((s->>'basis_points')::int) from jsonb_array_elements(p_state->'shares')s)<>10000 or exists(select 1 from jsonb_array_elements(p_state->'shares')s where (s->>'basis_points')::int not between 1 and 10000) or (select count(distinct s->>'person_id') from jsonb_array_elements(p_state->'shares')s)<>jsonb_array_length(p_state->'shares') then raise exception 'Hibás vagy zárolt teljesítménymegosztás.' using errcode='42501';end if;
  for subject in select (s->>'person_id')::uuid from jsonb_array_elements(p_state->'shares')s loop
   if not (ctx->'subjects'->'0') ? subject::text and not exists(select 1 from jsonb_array_elements(taskrow.state->'shares')s where s->>'person_id'=subject::text) then raise exception 'Idegen teljesítményrészesedés.' using errcode='42501';end if;
   if rank=1 and not exists(select 1 from jsonb_array_elements(p_state->'approvals')a where (a->>'level')::int=0 and a->'subjects' ? subject::text) then raise exception 'Dolgozó csak a fázis tényleges résztvevőit oszthatja meg.' using errcode='42501';end if;
  end loop;
 end if;
 update erp.project_tasks set state=p_state,planned_minutes=case when action_kind='time' then p_minutes::numeric else planned_minutes end,revision=revision+1 where id=p_task returning * into taskrow;
 update erp.workplans set revision=revision+1,updated_at=now() where id=plan.id;
 insert into erp.task_events(id,organization_id,project_id,task_id,actor_id,actor_auth_id,active_role,kind,request_payload,data,result_revision) values(p_request,plan.organization_id,p_project,p_task,person,p_actor,p_role,action_kind,p_command,p_event,taskrow.revision);
 if action_kind='reject' then
  update erp.work_notifications n set completed_at=now() where n.task_id=p_task and n.kind in ('review','repair','attribution') and n.completed_at is null;
  insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind,level) values(plan.organization_id,p_project,p_task,p_request,recipient,'repair',0);
  for subject in select distinct value::uuid from jsonb_array_elements_text(coalesce(p_event->'affected_actors','[]')||coalesce(p_event->'affected_subjects','[]')) loop
   if exists(select 1 from erp.persons where organization_id=plan.organization_id and id=subject) then insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,subject,'info') on conflict do nothing;end if;end loop;
 elsif action_kind='accept' then
  select max((a->>'level')::int) into highest from jsonb_array_elements(p_state->'approvals')a;
  update erp.work_notifications n set completed_at=now() where n.task_id=p_task and n.completed_at is null and ((n.kind='review' and n.level<=highest) or (n.kind='repair' and highest>=0));
  if level<3 and highest<level+1 then
   for recipient in select value::uuid from jsonb_array_elements_text(ctx->'subjects'->(level+1)::text) loop
    if recipient<>person then insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind,level) values(plan.organization_id,p_project,p_task,p_request,recipient,'review',level+1) on conflict do nothing;end if;end loop;
  end if;
 elsif action_kind='shares' then
  for recipient in select distinct (s->>'person_id')::uuid from jsonb_array_elements(coalesce(p_event->'before'->'shares','[]')||p_state->'shares')s loop
   insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,recipient,'info') on conflict do nothing;end loop;
 end if;
 if action_kind in ('shares','accept') and rank>=2 then
  for subject in select (s->>'person_id')::uuid from jsonb_array_elements(p_state->'shares')s loop
   if not exists(select 1 from erp.project_assignments a where a.organization_id=plan.organization_id and a.project_id=p_project and a.person_id=subject and a.revoked_at is null and a.valid_from<=now() and (a.valid_until is null or a.valid_until>now())) and not exists(select 1 from erp.person_roles r where r.organization_id=plan.organization_id and r.person_id=subject and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now())) then
    if p_role='office' then
     select min(a.valid_from) into future_day from erp.project_assignments a where a.organization_id=plan.organization_id and a.project_id=p_project and a.person_id=subject and a.revoked_at is null and a.valid_from>now();
     insert into erp.project_assignments(organization_id,project_id,person_id,role,valid_from,valid_until,created_by) values(plan.organization_id,p_project,subject,'construction_worker',now(),future_day,p_actor);
    else for recipient in select value::uuid from jsonb_array_elements_text(ctx->'subjects'->'2') loop insert into erp.work_notifications(organization_id,project_id,task_id,event_id,recipient_id,kind) values(plan.organization_id,p_project,p_task,p_request,recipient,'assignment') on conflict do nothing;end loop;end if;
   end if;
  end loop;
 end if;
 return jsonb_build_object('revision',taskrow.revision);end$$;

create or replace function public.erp_plan_read(p_actor uuid,p_session uuid,p_project uuid,p_role text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;plan erp.workplans;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);select * into plan from erp.workplans where project_id=p_project;
 return jsonb_build_object('context',ctx,'time',erp_private.worksheet_summary(p_project),'plan',case when plan.id is null then null else jsonb_build_object('id',plan.id,'revision',plan.revision,'quote_id',plan.quote_id,'quote_version',plan.quote_version,'execution_mode',plan.execution_mode,'execution_revision',plan.execution_revision) end,'tasks',coalesce((select jsonb_agg(erp_private.plan_task_json(t) order by t.sort,t.id) from erp.project_tasks t where t.plan_id=plan.id and erp_private.entry_task_active(t.id)),'[]'),
 'events',coalesce((select jsonb_agg(x.value order by x.created_at desc,x.id desc) from(select e.id,e.created_at,jsonb_build_object('id',e.id,'task_id',e.task_id,'actor_id',e.actor_id,'active_role',e.active_role,'kind',e.kind,'created_at',e.created_at,'data',e.data) as value from erp.task_events e where e.organization_id=plan.organization_id and e.project_id=p_project order by e.created_at desc,e.id desc limit 100)x),'[]'));
end$$;


create or replace function public.erp_plan_statistics(p_actor uuid,p_session uuid,p_project uuid,p_role text,p_from date default null,p_until date default null) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;begin
 ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if p_role='client' then raise exception 'A belső személyes statisztika ügyfélként nem érhető el.' using errcode='42501';end if;
 if p_from is not null and p_until is not null and p_until<p_from then raise exception 'Hibás időszak.' using errcode='22023';end if;
 if exists(select 1 from erp.workplans where project_id=p_project and execution_mode='parts')then
 return coalesce((with units as(
 select x->>'id'part_id,case when exists(select 1 from jsonb_array_elements(coalesce(x->'approvals','[]'))a where(a->>'level')::int=3)then x->>'id'else coalesce(x->'baseline'->>'source_task_id',x->'baseline'->>'source_part_id',x->>'id')end unit_id,erp_private.execution_approvals(x->'approvals',x->'baseline',coalesce((x->>'baseline_active')::boolean,false))approvals
 from erp.workplans w cross join lateral jsonb_array_elements(erp_private.execution_current_units(w.id))x where w.project_id=p_project),
 completed as(select unit_id from units u group by unit_id having bool_and(exists(select 1 from jsonb_array_elements(u.approvals)a where(a->>'level')::int=3 and(p_from is null or(a->>'at')::timestamptz>=p_from::timestamp at time zone 'Europe/Budapest')and(p_until is null or(a->>'at')::timestamptz<(p_until+1)::timestamp at time zone 'Europe/Budapest')))),
 participants as(select distinct(a->>'actor_id')::uuid person_id,u.unit_id from units u join completed c using(unit_id)cross join lateral jsonb_array_elements(u.approvals)a where(a->>'level')::int<3),
 rejections as(select e.id,e.task_id::text part_id,e.actor_id,e.data,e.created_at from erp.task_events e where e.project_id=p_project and e.kind='reject'and not(e.data?'execution_part_id')union all select e.id,e.part_id::text,e.actor_id,e.data,e.created_at from erp.execution_events e join erp.workplans w on w.id=e.plan_id where w.project_id=p_project and e.kind='reject'),
 affected as(select distinct e.id,coalesce(u.unit_id,e.part_id)unit_id,a.value::uuid person_id,e.actor_id returned_by,(e.data->>'recipient')::uuid recipient from rejections e left join units u on u.part_id=e.part_id cross join lateral jsonb_array_elements_text(coalesce(e.data->'affected_actors','[]'))a where(p_from is null or e.created_at>=p_from::timestamp at time zone 'Europe/Budapest')and(p_until is null or e.created_at<(p_until+1)::timestamp at time zone 'Europe/Budapest')),
 who as(select person_id from affected union select person_id from participants)
 select jsonb_agg(jsonb_build_object('person_id',p.id,'name',p.display_name,'returns',(select count(*)from affected a where a.person_id=p.id),'completed_tasks',(select count(*)from participants a where a.person_id=p.id),'first_pass_tasks',(select count(*)from participants a where a.person_id=p.id and not exists(select 1 from affected r where r.person_id=p.id and r.unit_id=a.unit_id)),
 'returned_by',coalesce((select jsonb_agg(jsonb_build_object('person_id',x.returned_by,'name',r.display_name,'count',x.n))from(select a.returned_by,count(*)n from affected a where a.person_id=p.id group by a.returned_by)x join erp.persons r on r.id=x.returned_by),'[]'),
 'repair_recipients',coalesce((select jsonb_agg(jsonb_build_object('person_id',x.recipient,'name',r.display_name,'count',x.n))from(select a.recipient,count(*)n from affected a where a.person_id=p.id group by a.recipient)x join erp.persons r on r.id=x.recipient),'[]'))order by p.display_name)
 from who join erp.persons p on p.id=who.person_id where p_role in('office','construction_lead')or p.id=(ctx->>'person_id')::uuid),'[]');end if;
 return coalesce((with affected as (
 select distinct e.id,e.task_id,x.value::uuid as person_id,e.actor_id as returned_by,(e.data->>'recipient')::uuid as recipient from erp.task_events e cross join lateral jsonb_array_elements_text(coalesce(e.data->'affected_actors','[]'))x where e.project_id=p_project and e.kind='reject' and (p_from is null or e.created_at>=p_from::timestamp at time zone 'Europe/Budapest') and (p_until is null or e.created_at<(p_until+1)::timestamp at time zone 'Europe/Budapest')
 ),completed as (
 select t.id as task_id from erp.project_tasks t join erp.workplans p on p.id=t.plan_id where p.project_id=p_project and exists(select 1 from jsonb_array_elements(t.state->'approvals')a where (a->>'level')::int=3 and (p_from is null or (a->>'at')::timestamptz>=p_from::timestamp at time zone 'Europe/Budapest') and (p_until is null or (a->>'at')::timestamptz<(p_until+1)::timestamp at time zone 'Europe/Budapest'))
 ),participants as (
 select distinct e.actor_id as person_id,e.task_id from erp.task_events e join completed c on c.task_id=e.task_id where e.project_id=p_project and e.kind='accept' and (e.data->>'level')::int<3
 ),who as (select person_id from affected union select person_id from participants)
 select jsonb_agg(jsonb_build_object('person_id',p.id,'name',p.display_name,'returns',(select count(*) from affected a where a.person_id=p.id),'completed_tasks',(select count(*) from participants a where a.person_id=p.id),'first_pass_tasks',(select count(*) from participants a where a.person_id=p.id and not exists(select 1 from erp.task_events e where e.project_id=p_project and e.task_id=a.task_id and e.kind='reject' and e.data->'affected_actors' ? p.id::text)),
 'returned_by',coalesce((select jsonb_agg(jsonb_build_object('person_id',x.returned_by,'name',r.display_name,'count',x.n)) from (select a.returned_by,count(*) as n from affected a where a.person_id=p.id group by a.returned_by)x join erp.persons r on r.id=x.returned_by),'[]'),
 'repair_recipients',coalesce((select jsonb_agg(jsonb_build_object('person_id',x.recipient,'name',r.display_name,'count',x.n)) from (select a.recipient,count(*) as n from affected a where a.person_id=p.id group by a.recipient)x join erp.persons r on r.id=x.recipient),'[]')) order by p.display_name) from who w join erp.persons p on p.id=w.person_id where p_role in ('office','construction_lead') or p.id=(ctx->>'person_id')::uuid),'[]');end$$;


do $$declare f record;begin for f in select p.oid::regprocedure signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='erp_private' and p.proname like 'execution_%') or(n.nspname='public' and p.proname like 'erp_execution_%')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);if f.nspname='public'then execute format('grant execute on function %s to service_role',f.signature);end if;end loop;end$$;
commit;
